    [232456] = { enName = "Emblem of the Violet Eye", enDescription = "Proof of victory over the Dark Riders. Redeemable at the Rune Broker in capital cities.", description = "Prova della vittoria sui Cavalieri Oscuri. Riscattabile presso il Mediatore delle Rune nelle città principali." },
    [232457] = { enName = "Emblem of the Worldcore", enDescription = "Proof of attuning to the Leyline Confluxes. Redeemable at the Rune Broker in capital cities.", description = "Prova di essersi sintonizzati sui Conflussi delle Linee Telluriche. Riscattabile presso il Mediatore delle Rune nelle città principali." },
    [232610] = { enName = "Formula: Magnificent Trollshine", itName = "Formula: Olio Magico", enDescription = "Teaches you how to create Magnificent Trollshine.", description = "Ti insegna a creare il Magnifico Trollshine." },
    [234817] = { enName = "Roots Within Stone", itName = "Ricetta: Stufato delle Marche Occidentali", enDescription = "An ancient text that details properties of long-lost rituals of the druids.", description = "Un antico testo che descrive le proprietà di rituali perduti da tempo dei druidi." },
    [234818] = { enName = "Essence Bottle", enDescription = "A strange fel energy emanates from the bottle.", description = "Dalla bottiglia emana una strana energia vile." },
    [235785] = { enName = "Deadwind Cage \"Key\"", enDescription = "Your astute powers of observation quickly determine that this \"key\" is really just a rock with a sharp edge on it. You suspect that simply bashing this against the lock should open the cage.", description = "Il tuo acuto spirito d’osservazione ti fa capire subito che questa \"chiave\" è in realtà solo una pietra con un bordo affilato. Sospetti che basti sbatterla contro la serratura per aprire la gabbia." },
    [235788] = { enName = "Enthusiastic Wisp", enDescription = "This thing just won't hold still...", description = "Questa cosa proprio non vuole stare ferma..." },
    [235852] = { enName = "Violet Satchel", itName = "Gemma di Mana di Dalaran", enDescription = "This small satchel bears the mark of the Kirin Tor of Dalaran. It seems to contain a few small objects but curiously, you find that you are unable to open the flap to see what is inside.", description = "Questa piccola bisaccia porta il marchio del Kirin Tor di Dalaran. Sembra contenere alcuni piccoli oggetti, ma curiosamente non riesci ad aprire la patta per vedere cosa c'è dentro." },
    [235867] = { enName = "Scrap of Parchment", itName = "Pezzi di Carta", enDescription = "The scrap of parchment appears to have been torn off of a larger poster or flyer. The only words legible on it seem to be a name ...Archmage Tarsis Kir-Moldir", description = "Il frammento di pergamena sembra essere stato strappato da un manifesto o volantino più grande. Le uniche parole leggibili sembrano essere un nome... Arcimago Tarsis Kir-Moldir" },
    [236754] = { enName = "Recipe: Distilled Firewater", itName = "Ricetta: Elisir dell'Agilità Minore", enDescription = "Teaches you how to craft Distilled Firewater.", description = "Ti insegna a creare Acqua di Fuoco Distillata." },
    [236872] = { enName = "Schematic: Creepy Censor Sensors", itName = "Progetto: Catena per Arma d'Acciaio", enDescription = "Teaches you how to craft Creepy Censor Sensors.", description = "Ti insegna a creare Sensori di Censura Inquietanti." },
    [236878] = { enName = "Mysterious Relic", enDescription = "Shadowy, yet unbroken. A relic of encroaching darkness.", description = "Ombroso, eppure intatto. Una reliquia dell'oscurità incombente." },
    [236879] = { enName = "Mysterious Relic", enDescription = "Discordant withering screams echo a harmonius bloom. The silvered edge outpours horror.", description = "Urla stridenti e laceranti riecheggiano un'armonica fioritura. Il bordo argentato riversa orrore." },
    [236880] = { enName = "Mysterious Relic", enDescription = "False eidolons cling to the unexposed hilt clamoring for the grip of an ancient king.", description = "Falsi eidolon si aggrappano all'elsa intonsa, reclamando la presa di un antico re." },
    [237196] = { enName = "Suspicious Collection Equipment", enDescription = "There don't seem to be any collection supplies in the barrel.", description = "Non sembra esserci alcun materiale da raccolta nel barile." },
    [237230] = { enName = "Suspicious Neutralizing Compound", enDescription = "The crate smells of charcoal.", description = "La cassa odora di carbone." },
    [238244] = { enName = "Tablet of Creation", enDescription = "Writings on the formation of arcane implements and weaponry.", description = "Scritti sulla creazione di strumenti e armi arcane." },
    [238245] = { enName = "Tablet of Manipulation", enDescription = "Writings on the magics of scrying and teleportation.", description = "Scritti sulle magie della chiaroveggenza e del teletrasporto." },
    [238246] = { enName = "Tablet of Power", enDescription = "Writings on the Well of Eternity and harnessing its cosmic energies.", description = "Scritti sul Pozzo dell'Eternità e sullo sfruttamento delle sue energie cosmiche." },
