    [238497] = { enName = "Air Elemental Core", itName = "Ricetta: Stufato delle Marche Occidentali", enDescription = "A broken core of an air elemental. It still smells faintly of gunpowder.", description = "Un nucleo spezzato di un elementale dell'aria. Odora ancora debolmente di polvere da sparo." },
    [238644] = { enName = "Demonic Energy Crystal Shard", itName = "Ricetta: Stufato delle Marche Occidentali", enDescription = "A strange fel energy pulses from within, but otherwise seems stable.", description = "Una strana energia vil pulsa al suo interno, ma per il resto sembra stabile." },
