    [238785] = { enName = "Schematic: Tinkerbox: Magnetic Displacement", enDescription = "Teaches you how to craft Tinkerbox: Magnetic Displacement.", description = "Ti insegna a creare Tinkerbox: Spostamento magnetico." },
    [238786] = { enName = "Schematic: Tinker: Teleport", enDescription = "Teaches you how to craft Tinker: Teleport.", description = "Ti insegna a creare Tinker: Teletrasporto." },
    [238787] = { enName = "Schematic: Tinker: Nitro Boosts", enDescription = "Teaches you how to craft Tinker: Nitro Boosts.", description = "Ti insegna a creare Tinker: Nitro boost." },
    [238788] = { enName = "Schematic: Tinker: Magnetic Displacement", enDescription = "Teaches you how to craft Tinker: Magnetic Displacement.", description = "Ti insegna a creare Tinker: Spostamento magnetico." },
    [238789] = { enName = "Schematic: Semisafe Transporter: New Avalon", enDescription = "Teaches you how to craft Semisafe Transporter: New Avalon.", description = "Ti insegna a creare Trasportatore semisicuro: Nuova Avalon." },
    [238794] = { enName = "Unappetizing Leftovers", itName = "Zucca di Tirisfal", enDescription = "Maybe starvation isn't so bad after all.", description = "Forse morire di fame non è poi così male." },
    [238797] = { enName = "Fel Crystal Shard", itName = "Ricetta: Stufato delle Marche Occidentali", enDescription = "A strong fel energy pulses from the shard.", description = "Dal frammento pulsa una potente energia vile." },
    [238798] = { enName = "Toxic Essence", itName = "Ricetta: Stufato delle Marche Occidentali", enDescription = "Faint fel energy oozes from the caustic goo.", description = "Dal muco caustico trasuda una debole energia vile." },
    [238802] = { enName = "Druidic Amulet", enDescription = "A faint calming energy emanates from the amulet.", description = "Dall'amuleto emana una debole energia calmante." },
    [238811] = { enName = "Juicy Apple", itName = "Zucca di Tirisfal", enDescription = "Fresh from the field.", description = "Appena raccolto sul campo." },
    [238830] = { enName = "Apple Scope", enDescription = "Used by the laziest of farmers to monitor their yield from the comfort of home.", description = "Usato dai contadini più pigri per controllare il raccolto comodamente da casa." },
    [238831] = { enName = "Apple Rope", enDescription = "It's just a regular rope.", description = "È solo una normale corda." },
    [238899] = { enName = "Assorted Fish", enDescription = "Your fishing skill is not high enough to identify most of these fish, but fortunately that is not your problem.", description = "La tua abilità di pesca non è abbastanza alta per identificare la maggior parte di questi pesci, ma per fortuna non è un problema tuo." },
    [238927] = { enName = "Pattern: Scarlet Quiver", enDescription = "Teaches you how to craft Scarlet Quiver.", description = "Ti insegna a creare Faretra scarlatta." },
    [238928] = { enName = "Pattern: Scarlet Ammo Pouch", enDescription = "Teaches you how to craft Scarlet Ammo Pouch.", description = "Ti insegna a creare Borsa per munizioni scarlatta." },
    [238935] = { enName = "Gently Plagued Meat", itName = "Zucca di Tirisfal", enDescription = "If you cut away the green parts, who is going to know?", description = "Se tagli via le parti verdi, chi se ne accorgerà?" },
    [238985] = { enName = "Heavy Crate", itName = "Zucca di Tirisfal", enDescription = "Deliver to the Scarlet Quartermaster to complete Prove Your Worth.", description = "Consegna al Quartiermastro Scarlatto per completare Dimostra il tuo valore." },
    [239006] = { enName = "Fel-Touched Flower", itName = "Ricetta: Stufato delle Marche Occidentali", enDescription = "Perverse energy emanates weakly from the once-beautiful flower.", description = "Dal fiore un tempo bellissimo emana una debole energia perversa." },
    [239013] = { enName = "Crystalline Axe", itName = "Lingotto di Sulfuron", enDescription = "Blades of Light, indeed.", description = "Lame di Luce, davvero." },
    [239016] = { enName = "Holy Salts", enDescription = "Commonly used by crusaders to ward off bad luck. Conveniently, it also useful for cooking.", description = "Usato comunemente dai crociati per scongiurare la sfortuna. Comodamente, è utile anche per cucinare." },
    [239017] = { enName = "Exquisite Spices", enDescription = "A highly regulated commodity; buying or selling directly would be unwise. Coveted by chefs when cooking feasts.", description = "Una merce sottoposta a rigide regolamentazioni; comprarla o venderla direttamente sarebbe imprudente. Molto ambita dagli chef per cucinare banchetti." },
    [239119] = { enName = "Holy Arrow", enDescription = "Blessed be the arrow that smites our enemies.", description = "Benedetta sia la freccia che abbatte i nostri nemici." },
    [239149] = { enName = "Pattern: Crusader's Knapsack", enDescription = "Teaches you how to craft Crusader's Knapsack.", description = "Insegna a creare la Borsa da viaggio del Crociato." },
    [239150] = { enName = "Pattern: Crimson Dawnwoven Bag", enDescription = "Teaches you how to craft Crimson Dawnwoven Bag.", description = "Insegna a creare la Borsa di tessuto dell'Alba cremisi." },
    [239218] = { enName = "Stoneshaper's Notes", itName = "Sangue di Montagna", enDescription = "This document is written in a sloppy shorthand but what you are able to understand suggest that these plans and project notes are the product of a true genius of a craftman.", description = "Questo documento è scritto in una stenografia sciatta, ma da ciò che riesci a capire sembra che questi progetti e appunti siano opera di un vero genio dell'artigianato." },
    [239222] = { enName = "Schematic: Pop-Up Shrub", enDescription = "Teaches you how to craft Pop-Up Shrub.", description = "Insegna a creare un Arbusto a comparsa." },
    [239223] = { enName = "House Prop", itName = "Zucca di Tirisfal", enDescription = "Incredibly convincing in the context of an opera or a play.", description = "Incredibilmente convincente nel contesto di un'opera o di uno spettacolo teatrale." },
    [239225] = { enName = "Classy Quill", itName = "Zucca di Tirisfal", enDescription = "You can only imagine the satisfaction of writing your own signature with this.", description = "Puoi solo immaginare la soddisfazione di scrivere la tua firma con questo." },
    [239246] = { enName = "Fizzlefuse's Shopping List", enDescription = "A list of items hastily scribbled down whenever it crossed the author's mind.", description = "Un elenco di oggetti annotati frettolosamente ogni volta che venivano in mente all'autore." },
    [239292] = { enName = "Forgewright's Notes", enDescription = "Contains the collected thoughts and works of Franclorn Forgewright.", description = "Contiene i pensieri e le opere raccolti di Franclorn Forgewright." },
    [239302] = { enName = "Scarlet Uniform Belt", enDescription = "A dense leather strap with a heavy steel buckle. Truly a masterpiece of a belt, ready to be ruined by reckless tinkering.", description = "Una spessa cinghia di cuoio con una pesante fibbia d'acciaio. Un vero capolavoro di cintura, pronta a essere rovinata da esperimenti sconsiderati." },
    [239545] = { enName = "Weathered Night Elf Artifact", enDescription = "Pitted erosion shows where this stone icon has succumbed to years of weathering.", description = "L'erosione butterata mostra come questa icona di pietra abbia ceduto a molti anni di intemperie." },
    [239698] = { enName = "Dawnwoven Fabric", enDescription = "Small pieces of cloth and thread that were mysteriously drawn toward the Crusader's Loom. Apparently used when stitching holy vestments.", description = "Piccoli pezzi di stoffa e filo misteriosamente attratti dal Telaio del Crociato. A quanto pare, si usano per cucire paramenti sacri." },
    [239704] = { enName = "Amulet of Gol'gere", enDescription = "A strange energy emanates from the worn elven amulet.", description = "Una strana energia emana dall'amuleto elfico logoro." },
    [239764] = { enName = "Crimson Bladeleaf", enDescription = "A vibrant red dye extracted from everything except the petals of a freshly bloomed Bladeleaf.", description = "Un vivace colorante rosso estratto da tutto tranne che dai petali di una Bladeleaf appena sbocciata." },
    [240846] = { enName = "Magnetic Scrap", enDescription = "One person's trash is another person's treasure, whether they like it or not!", description = "La spazzatura di qualcuno è il tesoro di qualcun altro, che gli piaccia o no!" },
    [240945] = { enName = "Slice of Carrie's Apple Pie", enDescription = "Despite the pie having been cut into three pieces of equal size, you somehow managed to get the smallest slice.", description = "Nonostante la torta sia stata tagliata in tre fette della stessa dimensione, in qualche modo sei riuscito a ottenere quella più piccola." },
    [241191] = { enName = "Formula: Enchant Weapon - Grand Crusader", enDescription = "Teaches you how to permanently enchant a weapon to occasionally bless the wielder with incredible strength.", description = "Insegna a incantare permanentemente un'arma affinché a volte benedica chi la impugna con una forza incredibile." },
    [241195] = { enName = "Formula: Enchant 2H Weapon - Grand Arcanist", enDescription = "Teaches you how to permanently enchant a two-handed melee weapon to occasionally bless the wielder with enhanced spell power.", description = "Insegna a incantare permanentemente un'arma da mischia a due mani affinché a volte benedica chi la impugna con un potere magico superiore." },
    [241201] = { enName = "Formula: Enchant Weapon - Grand Sorcerer", enDescription = "Teaches you how to permanently enchant a melee weapon to occasionally bless the wielder with enhanced spell power.", description = "Insegna a incantare permanentemente un'arma da mischia affinché a volte benedica chi la impugna con un potere magico superiore." },
    [241651] = { enName = "Recipe: Major Discolored Healing Potion", enDescription = "Teaches you how to craft Major Discolored Healing Potion.", description = "Insegna a creare una Pozione curativa scolorita maggiore." },
    [242018] = { enName = "Plaguelands Bleeding Heart", enDescription = "An unusually gorgeous flower given the region it is native to. It is capable of thriving despite the plague.", description = "Un fiore insolitamente splendido, considerando la regione in cui cresce. Riesce a prosperare nonostante la piaga." },
    [242224] = { enName = "Basket of Hearts", enDescription = "Perhaps not the best container one could pick for the situation.", description = "Forse non è il contenitore più adatto alla situazione." },
    [242266] = { enName = "World of Wardcraft", enDescription = "Filled cover to cover with thorough documentation of all things related to magical wards. Curiously, the book carries a subtle glow.", description = "Riempito dalla prima all'ultima pagina con una documentazione approfondita su tutto ciò che riguarda le protezioni magiche. Curiosamente, il libro emana un lieve bagliore." },
    [242267] = { enName = "From Arcanist to Archmage", enDescription = "A self-promoting autobiography written by an author too irrelevant to be named. Interestingly, the book also thrums with an attention seeking spell.", description = "Un'autobiografia autocelebrativa scritta da un autore troppo irrilevante per essere nominato. Curiosamente, il libro vibra anche per via di un incantesimo che cerca di attirare l'attenzione." },
    [242268] = { enName = "If You Give a Crusader an Enchant", enDescription = "An entertaining short story that quickly descends into madness before culminating in giving the antagonist everything he wants. Amusingly, the book shimmers with power.", description = "Un racconto breve e divertente che precipita rapidamente nella follia prima di culminare nel dare all'antagonista tutto ciò che vuole. Curiosamente, il libro brilla di potere." },
    [242361] = { enName = "Formula: Enchant 2H Weapon - Grand Inquisitor", enDescription = "Teaches you how to permanently enchant a two-handed melee weapon to occasionally bless the wielder with immense strength.", description = "Insegna a incantare in modo permanente un'arma da mischia a due mani affinché talvolta benedica chi la impugna con una forza immensa." },
    [242363] = { enName = "Who, What, Where, When, and Die! Five Keys to a Good Inquisition", enDescription = "Reading this left you with more questions than answers. What was this book even about? And why is it rumbling with great anticipation?", description = "Dopo averlo letto, hai più domande che risposte. Di cosa parlava questo libro, poi? E perché brontola con grande trepidazione?" },
    [243299] = { enName = "Big Bag o' Gold", enDescription = "Don't spend it all in one place.", description = "Non spenderlo tutto in un posto solo." },
    [245983] = { enName = "Ursine Heirloom", itName = "Pelle di Kodo Invecchiato", enDescription = "Well-worn and smoothed from age, this burl wood has the imprint of a bear paw carved into its surface. You have a strong desire to pass this on to another kindred spirit in need.", description = "Consumata e levigata dal tempo, questa radica di olmo presenta sulla superficie l'impronta scolpita di una zampa d'orso. Desideri ardentemente passarla a un altro spirito affine che ne ha bisogno." },
    [246885] = { enName = "Soft Cow Doll", enDescription = "You can tell that this doll was well-loved.", description = "Si capisce che questa bambola è stata molto amata." },
    [247000] = { enName = "Fel-Tainted Rock", enDescription = "Sparkling green vapors rise from this rock. You probably shouldn't touch it with bare skin too much.", description = "Da questa roccia salgono vapori verdi scintillanti. Probabilmente non dovresti toccarla troppo a lungo a mani nude." },
    [247001] = { enName = "Fel-Tainted Branch", enDescription = "Sparkling green vapors rise from this branch. Burning it would probably release toxic smoke.", description = "Da questo ramo salgono vapori verdi scintillanti. Bruciarlo probabilmente sprigionerebbe fumi tossici." },
    [247684] = { enName = "Forgotten Ashes", itName = "Pelle di Kodo Invecchiato", enDescription = "All that remains of a terrible thing", description = "Tutto ciò che resta di una cosa terribile" },
    [247786] = { enName = "Mote of Magic", itName = "Polvere Strana", enDescription = "Available from enchanting vendors.", description = "Disponibile presso i venditori di incantamento." },
    [247839] = { enName = "Stolen Book", itName = "Libro della Fattoria di Sven", enDescription = "Only slightly nibbled on.", description = "Morsicato appena appena." },
    [247840] = { enName = "Mining for Dummies", itName = "Libro della Fattoria di Sven", enDescription = "Explains how to mine using only the ten hundred most common words.", description = "Spiega come estrarre minerali usando solo le mille parole più comuni." },
    [247841] = { enName = "Wild Harvest", itName = "Libro della Fattoria di Sven", enDescription = "An instruction manual for picking wild herbs.", description = "Un manuale di istruzioni per raccogliere erbe selvatiche." },
    [247846] = { enName = "Pelt Collecting for Beginners", itName = "Libro della Fattoria di Sven", enDescription = "A picture book documenting how to collect animal skins.", description = "Un libro illustrato che documenta come raccogliere pelli di animali." },
    [247886] = { enName = "Sack of \"Picture\" Books", itName = "Libro della Fattoria di Sven", enDescription = "Every book in this sack is a children's picture book. Kobolds clearly can't read, but why do they want these books?", description = "Ogni libro in questo sacco è un libro illustrato per bambini. I kobold chiaramente non sanno leggere, ma perché vogliono questi libri?" },
    [248001] = { enName = "Lost Book", itName = "Libro della Fattoria di Sven", enDescription = "In fairly good condition, for being handled by kobolds.", description = "In condizioni abbastanza buone, considerando che è stato maneggiato dai kobold." },
    [248002] = { enName = "Picture Book: Fun with Elementals", itName = "Libro della Fattoria di Sven", enDescription = "This book is in pristine condition.", description = "Questo libro è in condizioni impeccabili." },
    [248003] = { enName = "Geomancy for Curious Young Wizards", itName = "Libro della Fattoria di Sven", enDescription = "This beautifully illustrated primer is covered in sticky spiderwebs, like someone recovered it from a spider's nest.", description = "Questo splendido abbecedario illustrato è ricoperto di ragnatele appiccicose, come se qualcuno l'avesse recuperato da un nido di ragni." },
    [248004] = { enName = "Arcane Explainer: Magical Stuff in Simple Words", itName = "Libro della Fattoria di Sven", enDescription = "A collection of annotated diagrams illustrating the principles of arcane artificery. It's covered in sticky spiderwebs.", description = "Una raccolta di diagrammi annotati che illustrano i principi dell'artigianato arcano. È ricoperta di ragnatele appiccicose." },
    [248549] = { enName = "Waylaid Crate", enDescription = "An eagerly awaited shipment that never arrived at its destination. Some of its supplies are missing.", description = "Una spedizione molto attesa che non è mai arrivata a destinazione. Mancano alcune delle provviste." },
    [248613] = { enName = "Lightning in a Bottle", enDescription = "The \"Lightning\" is just mustard.", description = "Il «Fulmine» è solo senape." },
    [249397] = { enName = "Tenets of the Silver Hand", itName = "Idolo della Ferocia", enDescription = "A pristine copy of the holy tome.", description = "Una copia impeccabile del tomo sacro." },
    [249432] = { enName = "Sandpaper", itName = "Tintura Gialla", enDescription = "Crafted by engineers.", description = "Realizzato dagli ingegneri." },
    [249474] = { enName = "Formula: Enchant Bracer - Minor Intellect", itName = "Formula: Incanta Arma - Cacciatore di Demoni", enDescription = "Teaches you how to permanently enchant bracers to give +3 Intellect.", description = "Insegna a incantare in modo permanente i bracciali per conferire +3 Intelletto." },
