    [249479] = { enName = "Formula: Enchant Weapon - Insight", itName = "Formula: Incanta Arma - Cacciatore di Demoni", enDescription = "Teaches you how to permanently enchant a weapon to grant a chance to gain Insight when you cast a spell, which gives +5% Spirit for a short duration.", description = "Ti insegna a incantare permanentemente un'arma, conferendole una probabilità di farti ottenere Intuito quando lanci un incantesimo, aumentando lo Spirito del 5% per un breve periodo." },
    [249480] = { enName = "Formula: Enchant Weapon - Recovery", itName = "Formula: Incanta Arma - Cacciatore di Demoni", enDescription = "Teaches you how to permanently enchant a weapon to grant a chance to trigger Recovery when your attacks are dodged or parried, which heals you for 5% of your maximum health. Cannot occur more than once every 10 sec.", description = "Ti insegna a incantare permanentemente un'arma, conferendole una probabilità di attivare Recupero quando i tuoi attacchi vengono schivati o parati, curandoti del 5% della salute massima. Non può verificarsi più di una volta ogni 10 s." },
    [249481] = { enName = "Formula: Enchant Weapon - Revelation", itName = "Formula: Incanta Arma - Cacciatore di Demoni", enDescription = "Teaches you how to permanently enchant a weapon to grant a chance to trigger Revelation when your direct spells fail to deal a critical strike. Revelation grants 100% increased critical strike chance to your next spell cast.", description = "Ti insegna a incantare permanentemente un'arma, conferendole una probabilità di attivare Rivelazione quando i tuoi incantesimi diretti non mettono a segno un colpo critico. Rivelazione aumenta del 100% la probabilità di colpo critico del tuo prossimo incantesimo." },
